import path from "node:path";

import { defineConfig, devices } from "@playwright/test";

const PORT = 3200;
const fixtureData = path.join(__dirname, "tests/e2e/.fixture-data");

/**
 * End-to-end tests run a production build in local mode against SYNTHETIC
 * data generated by the real ingestion pipeline (`npm run test:e2e` creates it).
 */
export default defineConfig({
  testDir: "tests/e2e",
  fullyParallel: true,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? "github" : "list",
  use: { baseURL: `http://localhost:${PORT}`, trace: "off" },
  projects: [
    { name: "desktop", use: { ...devices["Desktop Chrome"], viewport: { width: 1440, height: 900 } } },
    { name: "mobile", use: { ...devices["Pixel 7"] } },
  ],
  webServer: {
    command: `npm run build && npx next start -p ${PORT}`,
    url: `http://localhost:${PORT}/api/health`,
    reuseExistingServer: false,
    timeout: 240_000,
    env: { SYNAPSE_DATA_SOURCE: "local", SYNAPSE_DATA_DIR: fixtureData, NEXT_TELEMETRY_DISABLED: "1" },
  },
});
